#!/usr/bin/env python3
"""Minimal mock server emulating OpenAI-compatible endpoints for testing."""

import json
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer


class MockHandler(BaseHTTPRequestHandler):
    def _send_json(self, status, data):
        body = json.dumps(data).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path == "/v1/models":
            self._send_json(200, {
                "object": "list",
                "data": [
                    {"id": "mock-model-1", "object": "model"},
                    {"id": "mock-model-2", "object": "model"},
                ]
            })
        else:
            self._send_json(404, {"error": "not found"})

    def do_POST(self):
        if self.path == "/v1/responses":
            length = int(self.headers.get("Content-Length", 0))
            body = self.rfile.read(length)
            try:
                req = json.loads(body)
            except Exception:
                self._send_json(400, {"error": "invalid JSON"})
                return
            self._send_json(200, {
                "id": "resp_mock123",
                "object": "response",
                "model": req.get("model", "mock-model-1"),
                "choices": [
                    {
                        "index": 0,
                        "message": {
                            "role": "assistant",
                            "content": "Mock response to: " + str(req.get("messages", []))
                        },
                        "finish_reason": "stop"
                    }
                ]
            })
        else:
            self._send_json(404, {"error": "not found"})

    def log_message(self, fmt, *args):
        pass  # suppress request logs


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 9999
    server = HTTPServer(("localhost", port), MockHandler)
    print(f"Mock server listening on localhost:{port}", flush=True)
    server.serve_forever()

